package com.bank.union;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

// A tiny schema-aware DataFrame: ordered column names + rows keyed by column name.
class MiniFrame {
    final List<String> columns;          // ordered schema
    final List<Map<String, Object>> rows = new ArrayList<>();

    MiniFrame(List<String> columns) { this.columns = new ArrayList<>(columns); }

    // Add a row by giving values in the SAME order as this frame's columns.
    void addRow(Object... values) {
        Map<String, Object> row = new LinkedHashMap<>();
        for (int i = 0; i < columns.size(); i++) row.put(columns.get(i), values[i]);
        rows.add(row);
    }

    // Value of a column at a row index (or null if absent).
    Object valueAt(int rowIndex, String column) { return rows.get(rowIndex).getOrDefault(column, null); }
}
