package com.bank.union;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;
import java.util.logging.Logger;

// union(): aligns columns by POSITION. Wrong when column orders differ.
class PositionalUnion {
    private static final Logger log = Logger.getLogger(PositionalUnion.class.getName());

    MiniFrame union(MiniFrame a, MiniFrame b) {
        if (a.columns.size() != b.columns.size()) {
            throw new IllegalArgumentException("union() requires same column COUNT (got "
                    + a.columns.size() + " vs " + b.columns.size() + ")");
        }
        // Result uses a's column order; b's values are placed by index, not by name.
        MiniFrame result = new MiniFrame(a.columns);
        result.rows.addAll(a.rows);
        for (Map<String, Object> bRow : b.rows) {
            List<Object> bValuesInOrder = new ArrayList<>(bRow.values()); // b's ORDER
            Map<String, Object> mapped = new LinkedHashMap<>();
            for (int i = 0; i < a.columns.size(); i++) {
                mapped.put(a.columns.get(i), bValuesInOrder.get(i)); // POSITION-based: may scramble!
            }
            result.rows.add(mapped);
        }
        log.warning(() -> "union() combined by POSITION — if column orders differ, data is SCRAMBLED");
        return result;
    }
}
