package com.bank.union;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// unionByName(): aligns columns by NAME. Optional allowMissingColumns fills nulls.
class NameUnion {
    private static final Logger log = Logger.getLogger(NameUnion.class.getName());

    MiniFrame unionByName(MiniFrame a, MiniFrame b, boolean allowMissingColumns) {
        LinkedHashSet<String> allCols = new LinkedHashSet<>(a.columns);
        for (String c : b.columns) allCols.add(c);

        if (!allowMissingColumns && !new LinkedHashSet<>(a.columns).equals(new LinkedHashSet<>(b.columns))) {
            throw new IllegalArgumentException("unionByName without allowMissingColumns requires same column SET");
        }

        MiniFrame result = new MiniFrame(new ArrayList<>(allCols));
        appendByName(result, a, allCols);
        appendByName(result, b, allCols);
        log.info(() -> "unionByName combined by NAME (allowMissingColumns=" + allowMissingColumns
                + ") — columns aligned correctly regardless of order");
        return result;
    }

    private void appendByName(MiniFrame result, MiniFrame src, LinkedHashSet<String> allCols) {
        for (Map<String, Object> row : src.rows) {
            Map<String, Object> mapped = new LinkedHashMap<>();
            for (String col : allCols) {
                mapped.put(col, row.getOrDefault(col, null)); // NAME-based: missing → null
            }
            result.rows.add(mapped);
        }
    }
}
