package com.bank.union;

import java.util.List;
import java.util.logging.Logger;

public class UnionDemo {
    private static final Logger log = Logger.getLogger(UnionDemo.class.getName());

    public static void main(String[] args) {
        // Equities feed: account_id, symbol, amount
        MiniFrame equities = new MiniFrame(List.of("account_id", "symbol", "amount"));
        equities.addRow("SAV2001", "RELIANCE", 50000);

        // Derivatives feed: SAME columns but DIFFERENT order — amount before symbol.
        MiniFrame derivatives = new MiniFrame(List.of("account_id", "amount", "symbol"));
        derivatives.addRow("CUR3001", 80000, "NIFTY-FUT");

        log.info("=== Positional union() — WRONG when orders differ ===");
        MiniFrame bad = new PositionalUnion().union(equities, derivatives);
        // Look at the derivatives row (index 1): symbol column now holds the AMOUNT.
        log.warning(() -> "union() row for CUR3001: symbol=" + bad.valueAt(1, "symbol")
                + " amount=" + bad.valueAt(1, "amount") + "  (SCRAMBLED!)");

        log.info("=== unionByName() — CORRECT regardless of order ===");
        MiniFrame good = new NameUnion().unionByName(equities, derivatives, false);
        log.info(() -> "unionByName row for CUR3001: symbol=" + good.valueAt(1, "symbol")
                + " amount=" + good.valueAt(1, "amount") + "  (correct)");

        log.info("=== allowMissingColumns — new column on one side ===");
        MiniFrame newFeed = new MiniFrame(List.of("account_id", "symbol", "amount", "settlement_date"));
        newFeed.addRow("SAV2001", "TCS", 30000, "2026-11-01");
        MiniFrame merged = new NameUnion().unionByName(equities, newFeed, true);
        log.info(() -> "old equities row settlement_date = " + merged.valueAt(0, "settlement_date")
                + " (null, filled by allowMissingColumns)");
        log.info(() -> "new feed row settlement_date = " + merged.valueAt(1, "settlement_date"));
    }
}
